/// <summary>
/// READING GUIDE: Operators are PDF content-stream instructions. The hierarchy
/// groups instructions by role, while links retain operands and resolved resources.
/// The parser/adapter tracks graphics and text state and supplies the effective
/// font/color space at each instruction; this file does not execute drawing commands.
/// C# PORT: Use custom interfaces and a stateful content interpreter, not CLR
/// operator overloads or a drawing API. PDF tokens are case-sensitive: q/Q,
/// s/S, sc/SC and Tj/TJ have different meanings. Keep dispatch names distinct.
/// base class for all operators in the content stream
/// </summary>
/// <remarks>Source: Operator.mdl; Java: org.verapdf.model.operator.Operator.
/// </remarks>
public interface IOperator : global::VeraPdf.Model.BaseLayer.IModelObject
